// B02 입력 검사 (P11 골격). 계약 원본: WORKFLOW-DESIGN 6.1 Request, 6.4.1, 7.4.
// 규칙으로 판정 가능한 검사만 수행하고 LLM은 호출하지 않는다(WF-08 LLM 0회).
// codes 첫 값은 공통 코드 invalid_input, 뒤는 세부 사유다. 주입 패턴은 초기 목록이며 시험으로 보완한다.
const MAX_QUESTION = 500;
const MAX_ID = 64;
const DEADLINE_MS = 20000; // 일반 응답 20초는 초기 비교값(D05 실측 전)

const body = $json.body;
const codes = [];
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const str = (v) => (typeof v === 'string' ? v.trim() : null);

let request = null;
if (!isObj(body)) {
  codes.push('body_not_object');
} else {
  const request_id = str(body.request_id);
  const user = str(body.user);
  const question = str(body.question);
  if (request_id === null || request_id.length === 0) codes.push('request_id_required');
  else if (request_id.length > MAX_ID) codes.push('request_id_too_long');
  if (user === null || user.length === 0) codes.push('user_required');
  else if (user.length > MAX_ID) codes.push('user_too_long');
  if (question === null || question.length === 0) codes.push('question_empty');
  else if (question.length > MAX_QUESTION) codes.push('question_too_long');

  let attempt = 1;
  if (body.attempt !== undefined && body.attempt !== null) {
    if (!Number.isInteger(body.attempt) || body.attempt < 1) codes.push('attempt_invalid');
    else attempt = body.attempt;
  }
  for (const key of ['channel', 'context', 'case_ref']) {
    if (body[key] !== undefined && body[key] !== null && typeof body[key] !== 'string') {
      codes.push(`${key}_invalid`);
    }
  }
  request = {
    request_id: request_id ?? '',
    user: user ?? '',
    question: question ?? '',
    channel: str(body.channel) ?? undefined,
    attempt,
    context: str(body.context) ?? undefined,
    case_ref: str(body.case_ref) ?? undefined, // 6.1·6.4.5 현행 계약
  };
}

// 명백한 주입만 차단한다. 타인 기록 요청은 권한 문제(WF-06/07)라 여기서 막지 않는다.
const INJECTION = [
  /ignore\s+(all\s+|any\s+)?(previous|prior|above)\s+(instructions|prompts?|rules)/i,
  /disregard\s+(the\s+)?(system|previous)\s+(prompt|instructions)/i,
  /(reveal|print|show)\s+(me\s+)?(the\s+|your\s+)?system\s+prompt/i,
  /you\s+are\s+now\s+(a|an|in)\s/i,
  /(developer|dan|jailbreak)\s+mode/i,
  /(이전|앞|위)의?\s*(모든\s*)?(지시|지침|명령|규칙|프롬프트)\S*\s*(을|를|은|는)?\s*(전부\s*|모두\s*)?(무시|잊어)(?!\s*(해도|했|하면))/,
  /시스템\s*프롬프트\S*\s*(을|를)?\s*(보여|출력|알려|공개)/,
  /(너는|당신은)\s*이제(부터)?\s*.{0,20}(관리자|개발자|역할|시스템)/,
  /(관리자|운영자|개발자)\s*(권한|모드)\s*(으로|로)\s*((전환|실행|변경)\s*(해(?!야|도)|하라|하고|시켜)|바꿔(?!야|도))/,
  /<\s*\/?\s*(script|system|im_start|im_end)\b/i,
];
let blocked = false;
if (codes.length === 0) {
  const text = `${request.question}\n${request.context ?? ''}`;
  // 글자 사이를 띄운 한국어 지시도 잡는다. 영어 규칙은 단어 경계가 필요해 원문만 검사한다.
  const compact = text.replace(/\s+/g, '');
  const korean = INJECTION.filter((re) => /[가-힣]/.test(re.source));
  blocked = INJECTION.some((re) => re.test(text)) || korean.some((re) => re.test(compact));
}

const now = Date.now();
const security = { blocked_by: null, reason: null, masked: 0 };
let response = null;
let status = 200;
let error_code = null;

if (codes.length > 0) {
  status = 400;
  error_code = 'invalid_input';
  response = { error: 'invalid_input', codes: ['invalid_input', ...codes] };
} else if (blocked) {
  status = 200;
  error_code = 'prompt_injection';
  security.blocked_by = 'B02 입력 검사';
  security.reason = 'prompt_injection';
  response = {
    request_id: request.request_id,
    route: '차단',
    answer: '요청에 처리할 수 없는 지시가 포함되어 있어 접수하지 않았습니다. 따릉이 이용 문의만 다시 보내 주세요.',
    sources: [],
    ticket: null,
    agents: [],
    security,
    reason: 'prompt_injection',
  };
}

// headers는 인증 처리 후 업무 문맥·감사에 복사하지 않는다(6.1 WebhookBody).
return {
  json: {
    request,
    input_ok: codes.length === 0 && !blocked,
    actor: null,
    security,
    response,
    status,
    error_code,
    received_at: new Date(now).toISOString(),
    deadline_at: new Date(now + DEADLINE_MS).toISOString(),
  },
};

// B05 등록·권한 확인 (P11 골격). B04 full response를 받아 서버 기준 actor를 만든다.
// 요청 본문의 자기소개(역할·권한)는 사용하지 않는다(6.1 Actor, 6.4.1).
// 형식·권한 조합·오류 코드 원본: WORKFLOW-DESIGN 6.4.1, 7.4. R04·R05 검토 대기.
const ctx = $('B02 입력 검사').item.json; // 호출 직전 문맥 복원(6.1)
const raw = $json;
const statusCode = Number(raw.statusCode ?? raw.status ?? 0);
const body = raw.body;
const ROLE_LEVELS = {
  citizen: ['public'],
  support: ['public', 'restricted'],
  security: ['public', 'restricted'],
};
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isId = (v) => typeof v === 'string' && v.trim().length > 0;

// 권한 조합: 모든 역할은 public을 포함하고 역할별 허용 값만 중복 없이 가진다.
function validPermission(role, levels) {
  if (typeof role !== 'string' || !Object.hasOwn(ROLE_LEVELS, role)) return false;
  if (!Array.isArray(levels) || !levels.includes('public')) return false;
  if (new Set(levels).size !== levels.length) return false;
  return levels.every((level) => ROLE_LEVELS[role].includes(level));
}

// 등록 응답 → actor 또는 실패 코드. 팀 형식 {id,role,access_levels}, 과정 data-api 형식 {name,dept}만 허용.
function toActor(data, requestedUser) {
  if (!isObj(data)) return { code: 'user_lookup_invalid_response' };
  if (Object.hasOwn(data, 'id')) {
    if (!isId(data.id)) return { code: 'user_lookup_invalid_response' };
    if (data.id !== requestedUser) return { code: 'user_id_mismatch' };
    if (!validPermission(data.role, data.access_levels)) return { code: 'user_permission_invalid' };
    return { actor: { id: data.id, role: data.role, access_levels: [...data.access_levels] } };
  }
  const hasPermissionField = Object.hasOwn(data, 'role') || Object.hasOwn(data, 'access_levels');
  if (!isId(data.name) || !isId(data.dept) || hasPermissionField) {
    return { code: 'user_lookup_invalid_response' };
  }
  if (data.name !== requestedUser) return { code: 'user_id_mismatch' };
  // dept → 역할·권한 매핑은 R03/R04 확정 전이므로 승격 없이 최소 권한만 부여한다.
  return { actor: { id: data.name, role: 'citizen', access_levels: ['public'] } };
}

let actor = null;
let response = null;
let status = 200;
let error_code = null;

if (statusCode === 404) {
  status = 400;
  error_code = 'unknown_user';
  response = { error: 'unknown_user', codes: ['unknown_user'] };
} else {
  // 200 응답의 계약 위반과 조회 장애는 신원을 믿을 수 없으므로 같은 503으로 거절한다.
  const result = statusCode === 200 ? toActor(body, ctx.request.user) : { code: 'user_lookup_unavailable' };
  actor = result.actor ?? null;
  if (!actor) {
    status = 503;
    error_code = 'user_lookup_error';
    response = { error: 'user_lookup_error', codes: [result.code] };
  }
}

return { json: { ...ctx, actor, actor_ok: actor !== null, response, status, error_code } };

// B33 응답 구성: 저장 결과·재전송·거절·실패 결과를 공통 응답으로 정규화한다.
// 입력에 request가 없으면 B32의 SaveResult다. 이때 문맥은 B38에서 복원한다.
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
let ctx = $json;
if (!Object.hasOwn(ctx, 'request')) {
  const saved = ctx;
  const base = $('B38 저장 준비 결과 합성').first().json;
  const ok = isObj(saved) && saved.ok === true && saved.request_id === base.request.request_id && isObj(saved.state_ref);
  ctx = ok
    ? { ...base, state_ref: saved.state_ref, response: base.response_candidate, status: 200, response_ready: true, error_code: null }
    : { ...base, response_ready: false, status: 200, error_code: 'state_error', effect: 'unknown', recovery: saved?.recovery ?? null, known_ticket_id: base.support.ticket_id ?? null };
}
const response_ready = ctx.response_ready ?? true;
const r = ctx.response;
let body = null;
let status = Number.isInteger(ctx.status) ? ctx.status : 500;

if (!response_ready) {
  body = null;
} else if (r && typeof r.error === 'string') {
  body = { error: r.error, codes: Array.isArray(r.codes) ? r.codes : [] };
} else if (r && typeof r.route === 'string') {
  body = {
    request_id: r.request_id ?? ctx.request?.request_id ?? '',
    route: r.route,
    answer: r.answer ?? '',
    sources: Array.isArray(r.sources) ? r.sources : [],
    ticket: r.ticket ?? null,
    agents: Array.isArray(r.agents) ? r.agents : [],
    security: r.security ?? { blocked_by: null, reason: null, masked: 0 },
  };
  if (r.case_ref) body.case_ref = r.case_ref;
  if (r.reason) body.reason = r.reason;
  body.timings = { total_ms: Math.max(0, Date.now() - Date.parse(ctx.received_at)) };
} else {
  status = 500;
  body = { error: 'protocol_error', codes: ['response_missing'] };
}

// 감사 메타: 원문 질문·답변·연락처는 남기지 않는다(7.4).
const log = {
  request_id: ctx.request?.request_id ?? null,
  node: 'B33',
  route: body?.route ?? null,
  status,
  reason: body?.reason ?? ctx.error_code ?? null,
  masked: body?.security?.masked ?? 0,
  at: new Date().toISOString(),
};

return { json: { ...ctx, response_ready, http_status: status, http_body: body, log } };

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isStr = (v) => typeof v === 'string' && v.trim().length > 0;

// B08: BeginResult 검사와 이번 유효 보완 횟수 계산. 해시에 쓴 Request는 바꾸지 않는다.
const ctx = $('B05 등록·권한 확인').first().json;
const raw = $json;
const EMPTY = { summary: '', reported: [], confirmed: [], attempted_actions: [], missing: [], uncertainties: [], evidence_refs: [] };
const MODES = ['proceed', 'replay', 'pending', 'conflict', 'error'];
const base = { ...ctx, request_mode: 'error', state_ref: null, support: null, facts: EMPTY, urgent_dispatched: false, retrieval_done: false, ticket_required: true, ticket: null, known_ticket_id: null, agents: [], reason: null };
const valid = isObj(raw) && MODES.includes(raw.mode) && raw.request_id === ctx.request.request_id;
if (!valid) return { json: { ...base, error_code: 'protocol_error' } };
if (raw.mode === 'proceed') {
  const s = raw.support;
  if (!isObj(raw.state_ref) || !isObj(s) || !isStr(s.case_id) || !isObj(raw.facts) || s.owner_id !== ctx.actor.id) {
    return { json: { ...base, error_code: 'protocol_error' } };
  }
  const asked = ctx.request.attempt ?? 1;
  const attempt = ctx.request.case_ref ? Math.max(asked, Number(s.attempt ?? 0) + 1) : Math.max(1, asked);
  return { json: { ...base, request_mode: 'proceed', state_ref: raw.state_ref, support: { ...s, attempt }, facts: { ...EMPTY, ...raw.facts }, known_ticket_id: s.ticket_id ?? null, error_code: null } };
}
if (raw.mode === 'replay' && isObj(raw.response)) {
  const r = structuredClone(raw.response);
  if (isObj(r.ticket)) r.ticket.duplicate = true;
  return { json: { ...base, request_mode: 'replay', response: r, status: 200, error_code: null, response_ready: true } };
}
if ((raw.mode === 'pending' || raw.mode === 'conflict') && isObj(raw.response) && Number.isInteger(raw.http_status)) {
  return { json: { ...base, request_mode: raw.mode, response: raw.response, status: raw.http_status, error_code: raw.error_code ?? raw.response.error ?? null, response_ready: true } };
}
return { json: { ...base, state_ref: isObj(raw.state_ref) ? raw.state_ref : null, error_code: isStr(raw.error_code) ? raw.error_code : 'protocol_error' } };

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isStr = (v) => typeof v === 'string' && v.trim().length > 0;

const CONTACT = [/01[016789][- .]?\d{3,4}[- .]?\d{4}/g, /[\w.+-]+@[\w-]+\.[\w.-]+/g];
function mask(text, security) {
  let out = String(text ?? '');
  for (const re of CONTACT) out = out.replace(re, () => { security.masked += 1; return '[가림]'; });
  return out;
}

// B11: Triage 검사와 업무 판단. 순서: 긴급→분류 실패→한도→필수 정보→사람 판단→검색.
const ctx = $('B08 문맥 정리').first().json;
const raw = $json;
const TYPES = ['rental', 'return', 'breakdown', 'fees', 'followup', 'security', 'unknown'];
const REQUIRED = {
  rental: ['app_or_qr', 'symptom', 'attempted_actions'],
  return: ['bike_id', 'station_or_place', 'returned_at', 'lock_state'],
  breakdown: ['bike_id_or_place', 'symptom'],
  fees: ['usage_date', 'charge_detail'],
  followup: ['target_ticket_id'],
  security: ['exposure_detail'],
  unknown: [],
};
const security = { ...ctx.security };
const source = `${ctx.request.question}\n${ctx.request.context ?? ''}`;
function parse() {
  if (raw.error || typeof raw.text !== 'string') return { failure: 'llm_down' };
  try {
    const t = JSON.parse(raw.text.replace(/^```(?:json)?\s*|\s*```$/g, '').trim());
    const f = t.facts;
    const ok = isObj(t) && TYPES.includes(t.type) && ['normal', 'high'].includes(t.urgency)
      && Array.isArray(t.missing) && t.missing.every((m) => typeof m === 'string') && typeof t.needs_human === 'boolean'
      && isObj(f) && typeof f.summary === 'string' && Array.isArray(f.reported)
      && (t.target_ticket_id === null || typeof t.target_ticket_id === 'string');
    return ok ? { triage: t } : { failure: 'triage_invalid' };
  } catch {
    return { failure: 'triage_invalid' };
  }
}
const parsed = parse();
const attempt = ctx.support.attempt;
let plan;
let reason = null;
let triage = null;
let facts = ctx.facts;
if (parsed.failure) {
  plan = 'handoff';
  reason = parsed.failure;
} else {
  triage = parsed.triage;
  const stated = triage.facts.reported.filter((x) => isObj(x) && isStr(x.key) && isStr(x.value) && source.includes(x.value));
  const known = new Map(ctx.facts.reported.map((x) => [x.key, x]));
  for (const x of stated) known.set(x.key, { key: x.key, value: mask(x.value, security), origin: 'user' });
  if (triage.target_ticket_id && !source.includes(triage.target_ticket_id)) triage.target_ticket_id = null;
  const target = triage.target_ticket_id;
  const missing = triage.missing.filter((m) => REQUIRED[triage.type].includes(m) && !known.has(m) && !(m === 'target_ticket_id' && target));
  triage.missing = missing;
  facts = { ...ctx.facts, summary: mask(triage.facts.summary, security), reported: [...known.values()], missing };
  if (triage.urgency === 'high') { plan = 'urgent'; reason = 'urgent'; }
  else if (attempt >= 3) { plan = 'handoff'; reason = 'attempt_limit'; }
  else if (missing.length > 0) plan = 'ask';
  else if (triage.needs_human && !(triage.type === 'followup' && target)) { plan = 'handoff'; reason = 'needs_human'; }
  else plan = 'retrieve';
}
return { json: { ...ctx, triage, facts, plan, reason, security, agents: ['triage'] } };

const CONTACT = [/01[016789][- .]?\d{3,4}[- .]?\d{4}/g, /[\w.+-]+@[\w-]+\.[\w.-]+/g];
function mask(text, security) {
  let out = String(text ?? '');
  for (const re of CONTACT) out = out.replace(re, () => { security.masked += 1; return '[가림]'; });
  return out;
}

// B13: 검색·조회 요청을 각각 만든다. 필요 없는 갈래도 skipped 봉투를 받는다.
const ctx = $json;
const security = { ...ctx.security };
const target = ctx.triage?.target_ticket_id ?? null;
const query = mask(`${ctx.request.question} ${ctx.request.context ?? ''}`.trim(), security);
const searchOn = ctx.plan === 'urgent' || ctx.triage?.type !== 'followup';
return {
  json: {
    ...ctx,
    security,
    search_request: { request_id: ctx.request.request_id, enabled: searchOn, query, access_levels: ctx.actor.access_levels, deadline_at: ctx.deadline_at },
    lookup_request: { request_id: ctx.request.request_id, kind: 'lookup', enabled: Boolean(target), actor_id: ctx.actor.id, target_ticket_id: target },
  },
};

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isStr = (v) => typeof v === 'string' && v.trim().length > 0;

// B17: 봉투 2개 검사와 답변 경로 결정. 잘못된 봉투는 성공으로 추정하지 않는다.
const ctx = $('B13 검색·조회 준비').first().json;
const items = $input.all().map((item) => item.json);
const id = ctx.request.request_id;
const levels = ctx.actor.access_levels;
function envelope(raw, statuses) {
  if (!isObj(raw) || Number(raw.statusCode) !== 200 || !isObj(raw.body)) return null;
  if (raw.body.request_id !== id || !statuses.includes(raw.body.status)) return null;
  return raw.body;
}
function searchResult(raw) {
  const unavailable = { status: 'error', evidence: [], error_code: 'search_error' };
  if (!isObj(raw) || raw.error || !raw.statusCode || Number(raw.statusCode) >= 500) return unavailable;
  const b = envelope(raw, ['ok', 'empty', 'skipped', 'error']);
  if (!b || !Array.isArray(b.evidence)) return { status: 'error', evidence: [], error_code: 'protocol_error' };
  if (b.status === 'error') return { status: 'error', evidence: [], error_code: isStr(b.error_code) ? b.error_code : 'search_error' };
  if (b.status !== 'ok') return b.evidence.length === 0 ? { status: b.status, evidence: [], error_code: null } : { status: 'error', evidence: [], error_code: 'protocol_error' };
  const good = b.evidence.length > 0 && b.evidence.every((e) => isObj(e) && ['doc', 'section', 'chunk_id', 'text', 'version'].every((k) => isStr(e[k])) && Number.isFinite(e.score) && levels.includes(e.access_level));
  return good ? { status: 'ok', evidence: b.evidence, error_code: null } : { status: 'error', evidence: [], error_code: 'protocol_error' };
}
function lookupResult(raw) {
  const unavailable = { status: 'error', record: null, masked: 0, error_code: 'lookup_error' };
  if (!isObj(raw) || raw.error || !raw.statusCode || Number(raw.statusCode) >= 500) return unavailable;
  const b = envelope(raw, ['ok', 'skipped', 'denied', 'error']);
  if (!b) return { status: 'error', record: null, masked: 0, error_code: 'protocol_error' };
  const masked = Number.isInteger(b.masked) && b.masked > 0 ? b.masked : 0;
  if (b.status !== 'ok') return { status: b.status, record: null, masked, error_code: b.status === 'error' ? 'lookup_error' : null };
  const r = b.record;
  const good = isObj(r) && r.owner_id === ctx.actor.id && r.ticket_id === ctx.lookup_request.target_ticket_id && isStr(r.status);
  return good ? { status: 'ok', record: r, masked, error_code: null } : { status: 'error', record: null, masked: 0, error_code: 'protocol_error' };
}
const pair = items.length === 2;
const search = pair ? searchResult(items[0]) : { status: 'error', evidence: [], error_code: 'protocol_error' };
const lookup = pair ? lookupResult(items[1]) : { status: 'error', record: null, masked: 0, error_code: 'protocol_error' };
const searchOn = ctx.search_request.enabled;
const lookupOn = ctx.lookup_request.enabled;
let answer_plan = 'handoff';
let reason = ctx.reason;
if (ctx.plan === 'urgent' || lookup.status === 'denied') answer_plan = 'fixed';
else if (searchOn && search.status === 'error') reason = search.error_code;
else if (searchOn && search.status === 'skipped') reason = 'protocol_error';
else if (lookupOn && lookup.status !== 'ok') reason = lookup.error_code ?? 'protocol_error';
else if (!lookupOn && lookup.status !== 'skipped') reason = 'protocol_error';
else if (searchOn && search.status === 'empty') reason = 'no_evidence';
else if (searchOn) answer_plan = 'write';
else if (lookupOn) answer_plan = 'fixed';
else reason = 'protocol_error';
const security = { ...ctx.security, masked: ctx.security.masked + lookup.masked };
const agents = search.status === 'ok' ? [...new Set([...ctx.agents, 'retriever'])] : ctx.agents;
